spec.query:
from(bucket: "iot_data")
  |> range(start: -24h)
  |> filter(fn: (r) => r["_measurement"] == "sensor_readings")
  |> filter(fn: (r) => r["sensor_id"] == "sensor_003")
  |> filter(fn: (r) => r["_field"] == "movimento")
  |> last()
  |> map(fn: (r) => ({
      r with
      _value: if r._value then 1 else 0
  }))
